		PrintWriter out = new PrintWriter(System.out);
		StringTokenizer st = new StringTokenizer(in.readLine());
		long N = Long.parseLong(st.nextToken());
		long M = Long.parseLong(st.nextToken());
		long L = Long.parseLong(st.nextToken());
		long R = Long.parseLong(st.nextToken());
		if((N * M) % 2 == 1) {
			out.println(pow(R - L + 1, N * M));
		} else if((R - L + 1) % 2 == 0) {
			out.println((pow(R - L + 1, N * M) * (long)(998244353 + 1) / 2) % 998244353);
		} else {
			out.println(((pow(R - L + 1, N * M) + 1) * (long)(998244353 + 1) / 2) % 998244353);
		}
		in.close();
		out.close();
	}
	static long pow(long a, long b) {
		long res = 1;
		while(b > 0) {
			if(b % 2 == 1) {
				res = (res * a) % 998244353;
				b--;
			}
			a = (a * a) % 998244353;
			b /= 2;
		}
		return res;
	}
}
